SET NAMES utf8mb4;

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Дентальная имплантация',
'<p>Дентальные импланты — это искусственные корни зубов, которые устанавливаются в челюстную кость для восстановления отсутствующих зубов с точки зрения функции и эстетики. Возможность имплантации определяется совместной оценкой строения кости, здоровья дёсен, общего состояния здоровья и индивидуальных потребностей.</p>
<h2>Что такое дентальный имплант?</h2>
<p>Имплант — это искусственный корень, устанавливаемый в челюстную кость так, чтобы занять место корня утраченного зуба. Его задача — обеспечить опору со стороны кости для изготавливаемого на нём протеза. На импланте может быть выполнена одиночная коронка, мост, несущий несколько зубов, или несъёмный протез, охватывающий всю челюсть.</p>
<p>Какая ортопедическая конструкция подходит, определяется числом отсутствующих зубов, расположением промежутка, характером смыкания и эстетическими ожиданиями. Среди вариантов материалов для конструкции может рассматриваться и <a href="/ru/zirkonyum-dis-kaplama/">циркониевая коронка</a>.</p>
<p><img src="/assets/uploads/images/ts01-tek-dis-implant-kesiti.webp" alt="Имплант одиночного зуба в разрезе внутри челюстной кости" loading="lazy"  /></p>
<p><img src="/assets/uploads/images/ts01-implant-ustu-kuron-parcalari.webp" alt="Составные части коронки на импланте в разобранном виде" loading="lazy"  /></p>
<h2>Кому это может подойти?</h2>
<p>Вариант имплантации может рассматриваться у людей с отсутствием одного или нескольких зубов, у тех, кого не устраивает имеющийся протез, а также у тех, кто ищет несъёмное решение вместо съёмного протеза. Пригодность не зависит от одного критерия:</p>
<ul>
<li>Число отсутствующих зубов, расположение промежутка и состояние соседних зубов</li>
<li>Объём и качество челюстной кости</li>
<li>Здоровье дёсен и привычки ежедневной гигиены полости рта</li>
<li>Общее состояние здоровья, принимаемые препараты и курение</li>
</ul>
<p>Эти пункты можно оценить совместно только после осмотра и необходимой визуализации. Сравнительный обзор других вариантов при отсутствии зубов вы найдёте в нашем <a href="/ru/implant/">руководстве по лечению имплантами</a>.</p>
<h2>Оценка перед имплантацией</h2>
<p>Планирование не сводится к измерению промежутка. Вместе рассматриваются история здоровья, регулярно принимаемые препараты, состояние дёсен, объём и качество кости, характер смыкания и курение. С помощью необходимых методов визуализации изучаются высота и ширина кости, а также анатомическое соседство.</p>
<p>Ортопедическое планирование тоже выполняется на этом этапе: положение импланта определяется в соответствии с конструкцией будущего протеза. По итогам оценки вам сообщают варианты и предполагаемые этапы; до осмотра число имплантов, сроки или результат не обещаются.</p>
<h2>Как проходит лечение?</h2>
<ol>
<li><strong>Осмотр и визуализация</strong> — клинические данные и рентгенологическая оценка.</li>
<li><strong>Планирование</strong> — определение положения и числа имплантов, а также конструкции протеза.</li>
<li><strong>Установка импланта</strong> — хирургический этап под местной анестезией.</li>
<li><strong>Период заживления</strong> — время, необходимое для срастания импланта с костью (остеоинтеграции).</li>
<li><strong>Ортопедическая конструкция</strong> — снятие слепков и фиксация протеза.</li>
<li><strong>Контрольные осмотры</strong> — регулярное клиническое и при необходимости рентгенологическое наблюдение.</li>
</ol>
<p>Продолжительность этапов зависит от состояния кости, применённого метода и того, требуются ли дополнительные вмешательства.</p>
<p><img src="/assets/uploads/images/ts01-implant-tedavi-asamalari.webp" alt="Четыре этапа лечения дентальными имплантами" loading="lazy"  /></p>
<h2>Недостаток кости</h2>
<p>Увеличение объёма кости требуется не каждому пациенту. Если объём кости признан недостаточным, может потребоваться костная пластика или поднятие дна пазухи; необходимость определяется после визуализации. Подробнее об этих вмешательствах и о хирургическом процессе в целом см. страницу <a href="/ru/agiz-cerrahisi-uygulamalari/">операции в полости рта</a>.</p>
<p><img src="/assets/uploads/images/ts01-kemik-hacmi-karsilastirmasi.webp" alt="Сравнение достаточного и недостаточного объёма челюстной кости" loading="lazy"  /></p>
<h2>Долгосрочный успех</h2>
<p>На долгосрочный успех дентальных имплантов влияют многие факторы: правильный отбор случая, планирование, гигиена полости рта, курение, общее состояние здоровья, конструкция протеза и регулярные осмотры. Часть этих факторов находится в ведении врача, часть — в области повседневных привычек; поэтому период после лечения является неотъемлемой частью планирования.</p>
<h2>Уход после имплантации</h2>
<p>Рекомендации, которые даются после вмешательства, индивидуальны, и их выполнение напрямую влияет на заживление. Поскольку ткани вокруг импланта тоже могут воспаляться, не следует пренебрегать ежедневной чисткой, уходом за межзубными промежутками и регулярными осмотрами.</p>
<p>Если вы заметили нарастание отёка, непроходящую боль, кровоточивость десны, подвижность протеза или изменившееся ощущение при смыкании, рекомендуется записаться на контрольный приём.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Сколько длится лечение имплантами?</strong><br>Срок определяется не одной процедурой, а этапами. Период заживления, необходимый для срастания импланта с костью, зависит от состояния кости и применённого метода. На срок влияет и то, требуются ли дополнительные вмешательства. После осмотра и визуализации сообщаются предполагаемые этапы; фиксированные сроки не обещаются.</p>
<p><strong>Есть ли возрастные ограничения для имплантации?</strong><br>Верхней возрастной границы нет; определяющим является не возраст, а опора кости и дёсен и общее состояние здоровья. В отношении нижней границы ожидается завершение развития челюсти. Возможность определяется на осмотре.</p>
<p><strong>Чувствуется ли боль во время вмешательства?</strong><br>Установка импланта проводится под местной анестезией, и целью является комфорт процедуры. Могут ощущаться давление и вибрация. Поскольку индивидуальные ощущения различаются, полное отсутствие боли не гарантируется.</p>
<p><strong>Я курю — можно ли мне поставить имплант?</strong><br>Курение относится к факторам, способным неблагоприятно влиять на заживление вокруг импланта и на долгосрочный результат. Само по себе оно может не быть безусловным противопоказанием; однако риск открыто обсуждается с пациентом и планирование проводится с его учётом.</p>
<p><strong>У меня диабет или другое заболевание — это противопоказание?</strong><br>Системные заболевания сами по себе не означают противопоказания. Оцениваются степень их контроля, принимаемые препараты и, при необходимости, заключение соответствующего врача. Для некоторых групп препаратов может потребоваться дополнительная оценка.</p>
<p><strong>Что будет, если имплант не приживётся?</strong><br>Потеря импланта может произойти в ранний или поздний период, и причины у них разные. После оценки данных может рассматриваться повторное лечение, ожидание заживления области или альтернативные варианты. Для каждого случая путь не одинаков.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт возможность имплантации определяется совместной оценкой клинического осмотра, данных визуализации и ортопедических потребностей. MSc. Dt. Mehmet Taş окончил стоматологический факультет Стамбульского университета и завершил магистратуру по оральной хирургии и имплантологии в Университете UniCamillus в Италии.</p>
<p><a href="/ru/implant/">Лечение имплантами</a> · <a href="/ru/agiz-cerrahisi-uygulamalari/">Операции в полости рта</a> · <a href="/ru/zirkonyum-dis-kaplama/">Циркониевые коронки</a> · <a href="/ru/iletisim">Запись и контакты</a></p>',
'Варианты дентальной имплантации при отсутствии зубов; осмотр, оценка состояния кости, этапы лечения и период заживления.',
'Дентальная имплантация | MSc. Dt. Mehmet Taş',
'RU' FROM treatments WHERE link = 'dental-implant-tedavisi';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Операции в полости рта',
'<p>Операции в полости рта требуют клинической и рентгенологической оценки зубов, челюстной кости и окружающих тканей. Применяемый метод, объём вмешательства и период заживления планируются индивидуально. Dt. Mehmet Taş завершил магистратуру по оральной хирургии и имплантологии в Университете UniCamillus в Италии.</p>
<h2>Объём</h2><p>Под этим направлением рассматриваются оценка ретинированных зубов, хирургическое удаление зубов, резекция верхушки корня, увеличение объёма кости, синус-лифтинг и <a href="/ru/dental-implant-tedavisi/">имплантологическая хирургия</a>. Все вмешательства выполняются в нашей клинике MSc. Dt. Mehmet Taş и его командой.</p>
<h2>Оценка перед вмешательством</h2><p>Выясняются системные заболевания, принимаемые препараты, аллергии и риск кровотечения; клинический осмотр оценивается вместе с панорамным или трёхмерным снимком. Основу планирования составляет анатомическое соседство (пазуха, нервный канал).</p>
<h2>Ретинированный зуб мудрости</h2><p>Основанием для удаления могут быть боль, повторяющаяся инфекция, повреждение соседнего зуба, подозрение на кистозное образование или недоступные для гигиены участки. Не каждый ретинированный зуб удаляют; решение принимается совместно после осмотра и визуализации.</p>
<h2>Планирование хирургического удаления</h2><p>Подходящий хирургический доступ определяется по положению зуба, строению корня, отношению к кости и анатомическим образованиям; вмешательство проводится под местной анестезией.</p>
<h2>Период заживления</h2><p>Разъясняются назначения и рекомендации по уходу: давление марлевым тампоном в течение указанного врачом времени, охлаждение снаружи, отказ от курения и алкоголя, мягкая пища и отдых в первые дни, бережное отношение к области вмешательства и регулярная гигиена полости рта. При необычных проявлениях следует обратиться в клинику.</p>
<h2>Разъяснение рисков</h2><p>Отёк, боль, кровотечение, инфекция, временное ограничение подвижности и риски, связанные с анатомической близостью, разъясняются индивидуально до вмешательства.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Нужно ли удалять каждый зуб мудрости?</strong><br>Нет. Удаление рассматривается при наличии боли, повторяющейся инфекции, повреждения соседнего зуба, подозрения на кисту или положения, не допускающего гигиены. Для зубов, которые не вызывают жалоб и поддаются наблюдению, может быть предпочтено наблюдение.</p>
<p><strong>Сколько длится вмешательство и за сколько приёмов оно завершается?</strong><br>Это зависит от положения зуба, строения корня и отношения к кости. Большинство вмешательств завершается за один приём; в обширных случаях планирование может отличаться. Срок разъясняется после осмотра и визуализации.</p>
<p><strong>Будет ли потом отёк?</strong><br>Отёк, чувствительность и ограничение при жевании после хирургического вмешательства являются ожидаемыми проявлениями и обычно выражены в первые дни. При нарастающей боли, температуре, распространённом отёке или затруднении глотания и дыхания следует обратиться безотлагательно.</p>
<p><strong>Что можно есть после вмешательства?</strong><br>В первое время предпочтительна мягкая и тёплая пища, не нагружающая область вмешательства. Рекомендуется избегать очень горячей еды, питья через трубочку, курения и алкоголя. Подробные рекомендации даются индивидуально после процедуры.</p>
<p><strong>Я принимаю препараты, разжижающие кровь, — возможно ли вмешательство?</strong><br>Обязательно сообщите о принимаемых препаратах. Разжижающие кровь средства нельзя отменять без рекомендации врача. При необходимости планирование проводится с учётом заключения соответствующего врача.</p>
<p><strong>Нужно ли снимать швы?</strong><br>Это зависит от вида использованного шовного материала; часть швов рассасывается самостоятельно, часть снимается на контрольном приёме. О том, какой материал использован и когда прийти на контроль, сообщают после вмешательства.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт необходимость операции в полости рта оценивается с помощью клинического осмотра и необходимых методов визуализации.</p>
<p><a href="/ru/cerrahi/">Челюстно-лицевая хирургия</a> · <a href="/ru/dental-implant-tedavisi/">Дентальная имплантация</a> · <a href="/ru/kanal-tedavisi/">Лечение корневых каналов</a> · <a href="/ru/iletisim">Запись и контакты</a></p>',
'Осмотр, планирование и период заживления при ретинированных зубах мудрости, хирургическом удалении зубов и увеличении объёма кости.',
'Операции в полости рта | MSc. Dt. Mehmet Taş',
'RU' FROM treatments WHERE link = 'agiz-cerrahisi-uygulamalari';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Индивидуальный дизайн улыбки',
'<p>Дизайн улыбки — это не одна процедура, меняющая лишь цвет или форму зубов. Это индивидуальный процесс планирования, в котором вместе оцениваются зубы, дёсны, губы, пропорции лица и характер смыкания.</p>
<h2>Что такое дизайн улыбки?</h2>
<p>При дизайне улыбки эстетические ожидания не рассматриваются сами по себе; вместе с ними оцениваются здоровье полости рта, жевательная функция, сохранение тканей зуба и естественность вида. Цель — получить результат, гармоничный с лицом и устойчивый во времени.</p>
<h2>Что оценивается?</h2>
<ul>
<li>Цвет, форма и пропорции зубов</li>
<li>Уровни десны и соотношение губ и зубов</li>
<li>Линия улыбки и пропорции лица</li>
<li>Положение зубов и характер смыкания</li>
<li>Имеющиеся во рту пломбы и реставрации</li>
</ul>
<h2>Цифровое планирование</h2>
<p>В подходящих случаях трёхмерная запись, полученная внутриротовым сканером, помогает в планировании и изготовлении реставраций. Цифровое планирование — инструмент прогноза; оно не содержит обещания, что результат будет в точности таким же.</p>
<h2>Возможные виды лечения</h2>
<p>Вмешательства, которые могут потребоваться по итогам плана, различаются от человека к человеку: <a href="/ru/dis-beyazlatma/">отбеливание</a>, бондинг, виниры, E.max, <a href="/ru/zirkonyum-dis-kaplama/">циркониевые коронки</a>, контурирование десны, ортодонтическая оценка и восполнение отсутствующих зубов. Какие вмешательства подходят, определяется на осмотре.</p>
<h2>Процесс лечения</h2>
<ol>
<li>Осмотр и обсуждение ожиданий</li>
<li>Фотографии и цифровые записи</li>
<li>Оценка здоровья полости рта и смыкания</li>
<li>Разъяснение альтернатив</li>
<li>Предварительный просмотр в подходящих случаях</li>
<li>Выполнение</li>
<li>Контрольные приёмы</li>
</ol>
<h2>Естественный вид</h2>
<p>Естественный вид достигается за счёт гармоничных с лицом пропорций зубов, подходящей текстуры поверхности, светопроницаемости и уравновешенной линии улыбки. Единый стандартный вид не применяется ко всем.</p>
<h2>Показания</h2>
<p>При активном кариесе, заболевании дёсен или функциональной проблеме может потребоваться их лечение до эстетических вмешательств. Возможность определяется оценкой зубов, дёсен, смыкания и общего здоровья полости рта.</p>
<h2>Hollywood Smile</h2>
<p>Hollywood Smile — не стандартный пакет, а популярное выражение, описывающее более выраженные эстетические изменения. Не всем выполняются одно и то же вмешательство, одинаковая длина зубов и одинаковый цвет.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Дизайн улыбки — это одна процедура?</strong><br>Нет. Дизайн улыбки — процесс планирования; по его итогам могут потребоваться разные вмешательства: отбеливание, бондинг, виниры, цирконий, контурирование десны или ортодонтическая оценка. Какие из них подходят, определяется на осмотре.</p>
<p><strong>Нужно ли обтачивать зубы?</strong><br>Препарирование требуется не при каждом плане. В ряде случаев достаточно более щадящих вариантов, таких как отбеливание или бондинг. Объём подготовки зависит от текущего состояния зуба, исходного оттенка, желаемой формы и выбранного материала.</p>
<p><strong>Можно ли увидеть результат заранее?</strong><br>В подходящих случаях цифровое планирование и предварительный просмотр позволяют составить представление о возможном результате. Предварительный просмотр — инструмент планирования, а не обещание точного результата.</p>
<p><strong>Сколько длится процесс?</strong><br>Это зависит от объёма плана, необходимых подготовительных вмешательств и лабораторного этапа. При активном кариесе или заболевании дёсен сначала требуется их лечение, что также влияет на срок.</p>
<p><strong>При улыбке видно слишком много десны — это тоже можно спланировать?</strong><br>Уровни десны, подвижность губы и длина зубов входят в оценку. В подходящих случаях контурирование десны может стать частью плана; решение принимается по клиническим и рентгенологическим данным.</p>
<p><strong>Будет ли результат выглядеть естественно?</strong><br>Естественный вид достигается за счёт гармоничных с лицом пропорций зубов, подходящей текстуры поверхности, светопроницаемости и уравновешенной линии улыбки. Результат зависит от индивидуальных условий, и единый стандартный вид не применяется.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт варианты дизайна улыбки определяются совместной оценкой здоровья полости рта, сохранения тканей зуба, жевательной функции и задач естественной эстетики.</p>
<p><a href="/ru/estetik/">Эстетическая стоматология</a> · <a href="/ru/zirkonyum-dis-kaplama/">Циркониевые коронки</a> · <a href="/ru/dis-beyazlatma/">Отбеливание зубов</a> · <a href="/ru/iletisim">Запись и контакты</a></p>',
'При дизайне улыбки вместе оцениваются зубы, дёсны, пропорции лица и смыкание. Узнайте о цифровом планировании и ходе процесса.',
'Дизайн улыбки | Цифровое планирование | MSc. Dt. Mehmet Taş',
'RU' FROM treatments WHERE link = 'gulus-tasarimi';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Циркониевые коронки',
'<p>Циркониевые коронки — это керамические реставрации, предлагающие разные варианты материалов с точки зрения прочности, биологической совместимости и естественного вида. Не для каждого зуба подходит один и тот же материал или одна и та же технология изготовления; решение принимается на основании клинического осмотра и индивидуальных потребностей.</p>
<h2>Что такое циркониевая коронка?</h2>
<p>Это керамическая реставрация на основе диоксида циркония, охватывающая видимую часть зуба. Её цель — воссоздать утраченную форму, жевательную функцию и эстетику с помощью индивидуального планирования.</p>
<h2>В каких случаях она рассматривается?</h2>
<ul>
<li>Значительная утрата тканей и обширные реставрации</li>
<li>Сломанные или стёртые зубы</li>
<li>Изменение цвета и формы</li>
<li>Необходимость в мостовидном протезе</li>
<li>Необходимость реставрации на <a href="/ru/dental-implant-tedavisi/">импланте</a></li>
</ul>
<h2>Предварительная оценка</h2>
<p>Вместе оцениваются здоровье зубов и дёсен, сохранившиеся ткани зуба, смыкание, привычка сжимать зубы и скрежетать ими, эстетические ожидания и альтернативные методы лечения. Здоровые ткани зуба сохраняются насколько это возможно; коронка не преподносится как единственный вариант. Такие варианты, как бондинг, вкладки инлей/онлей, виниры или E.max, разъясняются в зависимости от показаний.</p>
<h2>Цифровой рабочий процесс</h2>
<ol>
<li>Осмотр и получение записей</li>
<li>Необходимая подготовка</li>
<li>Внутриротовое сканирование или слепок</li>
<li>Цифровое моделирование и примерка</li>
<li>Изготовление</li>
<li>Контроль прилегания, смыкания и эстетики</li>
<li>Фиксация</li>
</ol>
<h2>Монолитный и облицованный вариант</h2>
<p>Монолитный диоксид циркония изготавливается цельным и ориентирован на прочность. При облицованном подходе эстетическая керамика позволяет улучшить цвет, текстуру и поведение света. Выбор делается в зависимости от положения зуба и приходящейся на него нагрузки.</p>
<h2>Разница между цирконием и E.max</h2>
<p>Цирконий предлагает разные варианты прочности и светопроницаемости; дисиликат лития (широко известный как E.max) может выделяться светопроницаемостью особенно в отдельных эстетических участках. Выбор делается в зависимости от положения зуба и условий нагрузки.</p>
<table>
<thead><tr><th>Параметр</th><th>Цирконий</th><th>E.max / дисиликат лития</th></tr></thead>
<tbody>
<tr><td>Сильная сторона</td><td>Варианты прочности и широкая область применения</td><td>Высокая светопроницаемость и эстетическая характеризация</td></tr>
<tr><td>Примечание к планированию</td><td>Включая боковой отдел, мосты и конструкции на имплантах; тип материала выбирается по эстетическим требованиям.</td><td>Может рассматриваться в отдельных случаях во фронтальном отделе и при реставрации одиночных зубов.</td></tr>
<tr><td>Критерий решения</td><td colspan="2">Ни один материал не превосходит остальные для всех. Определяющими вместе являются ткани зуба, его положение, сила смыкания, исходный оттенок, протяжённость реставрации и эстетическая задача.</td></tr>
</tbody>
</table>
<h2>Как планируется естественный вид?</h2>
<p>Вместе оцениваются цвет соседних зубов, текстура поверхности, прозрачность, десневой контур, пропорции зубов, линия улыбки и вид при разном освещении. Для целостного эстетического плана см. также страницу <a href="/ru/gulus-tasarimi/">дизайн улыбки</a>.</p>
<h2>Уход и контрольные осмотры</h2>
<p>Ежедневная чистка, уход за межзубными промежутками, поддержание здоровья дёсен и регулярные осмотры напрямую влияют на долгосрочный результат. При привычке сжимать зубы и скрежетать ими может рассматриваться защитная каппа.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Сколько служит циркониевая коронка?</strong><br>Фиксированный срок или гарантия службы не предоставляются. На долгосрочный результат влияют выбор материала, подготовка, смыкание, гигиена полости рта, привычка сжимать зубы и регулярные осмотры.</p>
<p><strong>Выглядит ли цирконий естественно?</strong><br>При правильном подборе цвета, текстуры поверхности, толщины и лабораторной характеризации можно приблизиться к естественному виду; результат зависит от индивидуальных условий.</p>
<p><strong>Нужно ли обтачивать зуб?</strong><br>Необходимый объём подготовки зависит от текущего состояния зуба и выбранной реставрации. Более щадящие альтернативы рассматриваются на осмотре.</p>
<p><strong>Цирконий или E.max?</strong><br>Это решение принимается не только по эстетическим соображениям. Вместе оцениваются положение зуба, сохранившиеся ткани, жевательная нагрузка, исходный оттенок и конструкция реставрации.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт возможность изготовления циркониевых коронок определяется совместной оценкой сохранившихся тканей зуба, здоровья дёсен, характера смыкания и эстетических ожиданий.</p>
<p><a href="/ru/estetik/">Эстетическая стоматология</a> · <a href="/ru/gulus-tasarimi/">Индивидуальный дизайн улыбки</a> · <a href="/ru/dental-implant-tedavisi/">Дентальная имплантация</a> · <a href="/ru/iletisim">Запись и контакты</a></p>',
'В каких случаях рассматриваются циркониевые коронки? Цифровое планирование, естественный вид, отличие от E.max и рекомендации по уходу.',
'Циркониевые коронки | MSc. Dt. Mehmet Taş',
'RU' FROM treatments WHERE link = 'zirkonyum-dis-kaplama';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Лечение корневых каналов',
'<p>Цель лечения корневых каналов — по возможности сохранить в полости рта зуб, пульпа которого необратимо повреждена или инфицирована. Решение о лечении принимается не только по наличию боли, а на основании совместной оценки осмотра, тестов пульпы и данных визуализации.</p>
<p>В нашей клинике лечение корневых каналов выполняет врач-эндодонт <strong>под увеличением с использованием бинокулярной лупы</strong>. Повторное лечение ранее пролеченного канала (ретритмент) и при необходимости резекция верхушки корня (апикальная резекция) проводятся в том же объёме.</p>
<h2>Что такое лечение корневых каналов?</h2>
<p>Это очистка, формирование, дезинфекция и пломбирование подходящим материалом корневых каналов в случае, когда пульпа зуба необратимо повреждена или инфицирована.</p>
<h2>В каких случаях оно рассматривается?</h2>
<p>Поводом для лечения корневых каналов могут стать глубокий кариес, травма, трещина или перелом, воспаление или некроз пульпы, признаки инфекции в тканях у верхушки корня и отдельные реставрационные задачи.</p>
<h2>Какими могут быть проявления?</h2>
<p>Возможны самопроизвольная или ночная боль, затяжная реакция на горячее и холодное, боль при жевании, отёк, изменение цвета зуба или выделения из десны. Некоторые зубы могут не давать никаких проявлений; поэтому важны регулярные осмотры.</p>
<h2>Диагностика и планирование</h2>
<p>Совместно оцениваются история боли, клинический осмотр, тесты пульпы, данные перкуссии и пальпации, состояние дёсен и необходимые рентгеновские снимки. Решение не принимается по одному отдельному признаку.</p>
<p><strong>Важное разъяснение:</strong> антибиотик не заменяет механическую очистку инфицированного корневого канала. Необходимость в лекарственных средствах при системных проявлениях или риске распространения оценивается врачом отдельно.</p>
<h2>Как проходит лечение?</h2>
<ol>
<li>Местная анестезия и изоляция</li>
<li>Формирование доступа</li>
<li>Определение рабочей длины и анатомии каналов</li>
<li>Очистка, формирование и промывание (ирригация)</li>
<li>Пломбирование каналов</li>
<li>Коронковая герметизация и контроль</li>
</ol>
<h2>За один приём или за несколько?</h2>
<p>Число приёмов зависит от состояния пульпы, признаков инфекции, анатомии каналов, необходимости повторного лечения и клинических условий. До осмотра фиксированное число приёмов не обещается.</p>
<h2>Повторное лечение корневых каналов</h2>
<p>При сохраняющихся проявлениях, подтекании, пропущенном канале, недостаточном пломбировании или подозрении на новую инфекцию может рассматриваться удаление прежнего пломбировочного материала и повторное лечение. Это вмешательство также выполняет в нашей клинике врач-эндодонт.</p>
<h2>Реставрация и наблюдение</h2>
<p>Нужна ли на пролеченный зуб пломба, вкладка онлей или коронка, определяется сохранившимися тканями зуба, риском трещины, положением зуба и жевательной нагрузкой. Проводится клиническое и при необходимости рентгенологическое наблюдение.</p>
<table>
<thead><tr><th>Вариант</th><th>Когда он может рассматриваться?</th><th>Примечание к планированию</th></tr></thead>
<tbody>
<tr><td>Прямая композитная пломба</td><td>Достаточно здоровых тканей и ограниченная утрата вещества</td><td>Важны коронковая герметизация и контроль смыкания.</td></tr>
<tr><td>Онлей / оверлей</td><td>Отдельные случаи, когда требуется перекрытие бугров, но полное круговое покрытие не обязательно</td><td>Может рассматриваться как адгезивный вариант, сохраняющий оставшиеся ткани.</td></tr>
<tr><td>Полная коронка</td><td>Значительная утрата тканей, риск трещины или имеющиеся реставрационные условия</td><td>Это не автоматическое требование для каждого зуба после лечения каналов. <a href="/ru/zirkonyum-dis-kaplama/">Циркониевая коронка</a> — один из вариантов.</td></tr>
</tbody>
</table>
<p>Тип реставрации подбирается индивидуально после осмотра с учётом сохранившихся здоровых тканей, положения зуба, жевательной нагрузки, риска трещины и условий изоляции.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Больно ли лечить корневые каналы?</strong><br>Местная анестезия направлена на комфорт процедуры; на ощущения могут влиять степень воспаления и индивидуальные условия. Полное отсутствие боли не гарантируется.</p>
<p><strong>Нормальна ли боль после лечения?</strong><br>В первые дни возможна чувствительность при жевании. При нарастающей боли, заметном отёке, температуре или затруднении глотания и дыхания следует обратиться в клинику безотлагательно.</p>
<p><strong>Нужна ли коронка на каждый зуб после лечения каналов?</strong><br>Нет. В зависимости от сохранившихся тканей, группы зуба, риска трещины и функциональной нагрузки реставрацией может быть пломба, онлей или коронка.</p>
<p><strong>Что делать, если лечение оказалось неуспешным?</strong><br>В зависимости от диагноза могут рассматриваться повторное лечение каналов, резекция верхушки корня или удаление; не каждый вариант подходит для каждого зуба.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт необходимость лечения корневых каналов определяется совместной оценкой клинического осмотра, тестов пульпы и необходимых данных визуализации.</p>
<p><a href="/ru/agiz-dis-sagligi/">Здоровье полости рта и зубов</a> · <a href="/ru/zirkonyum-dis-kaplama/">Циркониевые коронки</a> · <a href="/ru/agiz-cerrahisi-uygulamalari/">Операции в полости рта</a> · <a href="/ru/iletisim">Запись и контакты</a></p>',
'В каких случаях проводится лечение корневых каналов? Проявления, диагностика, этапы лечения и варианты последующей реставрации.',
'Лечение корневых каналов | Этапы и последующий уход | MSc. Dt. Mehmet Taş',
'RU' FROM treatments WHERE link = 'kanal-tedavisi';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Кариес и композитные пломбы',
'<p>Композитная пломба может использоваться для восполнения тканей зуба, утраченных из-за кариеса, перелома или прежней реставрации, с помощью адгезивного материала цвета зуба. Не всякое изменение цвета требует пломбы; решение принимается по активности, глубине и доступности очага для очищения.</p>
<h2>Что такое кариес?</h2>
<p>Кариес — это процесс потери минералов, в котором совместно участвуют биоплёнка, сбраживаемые углеводы, время, слюна и индивидуальные факторы риска. Ранние очаги не всегда образуют полость.</p>
<p><img src="/assets/uploads/images/ts12-curugun-ilerleyisi.webp" alt="Схема в разрезе, показывающая распространение кариеса в эмали, дентине и к пульпе" loading="lazy"  /></p>
<h2>Проявления</h2>
<p>Возможны чувствительность к холодному, горячему или сладкому, боль при жевании, застревание пищи или заметное изменение цвета. Однако часть контактных очагов может развиваться без каких-либо проявлений; поэтому важны регулярные осмотры.</p>
<h2>Клиническая и рентгенологическая оценка</h2>
<p>Исследуются вид поверхности и возможность её очищения, наличие полости, соседние зубы, прежние реставрации и близость к пульпе. При необходимости к оценке добавляется прикусный (bite-wing) или периапикальный снимок.</p>
<p><img src="/assets/uploads/images/ts12-klinik-ve-radyografik-degerlendirme.webp" alt="Совместная оценка кариеса при клиническом осмотре и по рентгеновскому снимку" loading="lazy"  /></p>
<h2>План лечения</h2>
<p>При ранних очагах без образования полости бывает достаточно контроля факторов риска, фторидов и наблюдения. При очагах, недоступных для очищения или вызывающих структурную утрату, рассматривается щадящее реставрационное лечение. Цель не только в удалении потемневших тканей, но и в контроле активности кариеса, защите пульпы и максимальном сохранении здоровых тканей зуба.</p>
<h2>Ход композитной реставрации</h2>
<ol>
<li>Подбор цвета и изоляция</li>
<li>Контролируемое удаление поражённых тканей</li>
<li>Адгезивная подготовка</li>
<li>Послойное внесение композита</li>
<li>Контроль контактного пункта, анатомии и смыкания</li>
<li>Финишная обработка и полировка</li>
</ol>
<p><img src="/assets/uploads/images/ts12-kompozit-dolgu-asamalari.webp" alt="Схематичный рисунок, показывающий этапы адгезивной композитной реставрации" loading="lazy"  /></p>
<h2>Глубокий кариес и пульпа</h2>
<p>При близости к пульпе вместе оцениваются история боли, тесты витальности, рентгенологические данные и сохранившиеся ткани зуба. В разных ситуациях могут рассматриваться избирательное удаление поражённых тканей, вмешательство для защиты пульпы или <a href="/ru/kanal-tedavisi/">лечение корневых каналов</a>.</p>
<p><img src="/assets/uploads/images/ts12-dolgu-ve-kanal-kapsam-farki.webp" alt="Сравнение, показывающее разницу в объёме между пломбой и лечением корневых каналов" loading="lazy"  /></p>
<h2>Период после вмешательства</h2>
<p>До окончания действия анестезии рекомендуется быть осторожным при приёме пищи. Возможна кратковременная чувствительность; при завышенном контакте, затяжной самопроизвольной боли или боли при жевании проводится контроль.</p>
<h2>Уход и наблюдение</h2>
<p>Важны чистка зубов, уход за межзубными промежутками, питание и план применения фторидов в соответствии с риском кариеса, а также регулярные осмотры. Наблюдают за краем пломбы, контактным пунктом, стираемостью, сколами и риском вторичного кариеса.</p>
<h2>Реставрационные варианты в зависимости от утраты тканей</h2>
<table>
<thead><tr><th>Вариант</th><th>Объём</th><th>Примечание к планированию</th></tr></thead>
<tbody>
<tr><td>Прямая композитная пломба</td><td>Восполнение утраченных тканей адгезивным материалом непосредственно в полости рта</td><td>Может быть щадящим вариантом при ограниченной утрате тканей, поддающейся надлежащей изоляции.</td></tr>
<tr><td>Инлей / онлей</td><td>Непрямая реставрация лабораторного или цифрового изготовления</td><td>При более значительной утрате вещества может рассматриваться с учётом опоры оставшихся стенок и бугров.</td></tr>
<tr><td>Коронка</td><td>Реставрация, более полно охватывающая коронковую часть зуба</td><td>Может потребоваться при значительной структурной утрате или риске перелома; нужна не каждому зубу с кариесом. <a href="/ru/zirkonyum-dis-kaplama/">Циркониевая коронка</a> — один из вариантов.</td></tr>
<tr><td>Лечение корневых каналов и реставрация</td><td>Лечение системы каналов, если пульпа необратимо поражена или некротизирована</td><td>Решение принимается не только по виду кариеса, но и по проявлениям, тестам и рентгенологическим данным.</td></tr>
</tbody>
</table>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Всякий ли кариес вызывает боль?</strong><br>Нет. Особенно ранние или контактные очаги могут не давать проявлений. Осмотр и при необходимости рентгеновский снимок обеспечивают оценку, не опирающуюся только на боль.</p>
<p><strong>Всякий ли тёмный участок — кариес?</strong><br>Нет. Потемнение может быть пигментацией, остановившимся очагом, особенностью анатомии фиссур или следствием прежней реставрации. Активность, строение поверхности и данные визуализации оцениваются вместе.</p>
<p><strong>Нормальна ли чувствительность после пломбирования?</strong><br>Возможна кратковременная чувствительность; влиять могут глубина, близость к пульпе и смыкание. При усиливающейся, самопроизвольной или затяжной боли требуется контроль.</p>
<p><strong>Сколько служит композитная пломба?</strong><br>Фиксированный срок или гарантия службы не предоставляются. На результат влияют размер и положение пломбы, изоляция, смыкание, привычка сжимать зубы, уход и риск кариеса.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт необходимость лечения кариеса и композитной реставрации определяется совместной оценкой клинического осмотра, необходимых снимков, состояния пульпы, характера смыкания и риска кариеса.</p>
<p><a href="/ru/agiz-dis-sagligi/">Здоровье полости рта и зубов</a> · <a href="/ru/kanal-tedavisi/">Лечение корневых каналов</a> · <a href="/ru/zirkonyum-dis-kaplama/">Циркониевые коронки</a> · <a href="/ru/iletisim">Запись и контакты</a></p>',
'Как распознать кариес? Клиническая и рентгенологическая оценка, этапы композитной реставрации и подход при глубоком кариесе.',
'Кариес и композитные пломбы | MSc. Dt. Mehmet Taş',
'RU' FROM treatments WHERE link = 'dis-curugu-kompozit-dolgu';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Отбеливание зубов',
'<p>Отбеливание зубов — эстетическая процедура, цель которой сделать имеющийся оттенок собственных тканей зуба светлее. Достижимое изменение индивидуально; результат определяют исходный цвет, тип окрашивания, строение зуба, выбранный протокол и личная реакция. Поэтому определённое число тонов или точный результат заранее не обещаются.</p>
<p>Отбеливание не скрывает имеющиеся во рту проблемы. При кариесе, негерметичной пломбе, воспалении дёсен или обнажённой поверхности корня сначала устраняются эти состояния; отбеливание рассматривается после завершения этих этапов.</p>
<h2>Что такое отбеливание зубов?</h2>
<p>Это процедура, направленная на осветление окрашиваний в собственных тканях зуба с помощью врачебной оценки и подходящих протоколов на основе пероксида. Отбеливающий состав химически изменяет окрашенные молекулы внутри эмали и дентина.</p>
<p>Это не то же самое, что удаление зубных отложений и полировка: чистка удаляет отложения и поверхностные пятна с поверхности зуба, тогда как отбеливание направлено на изменение собственного оттенка тканей. У части людей заметное осветление наступает уже после чистки и полировки, и отбеливание может не потребоваться.</p>
<h2>Почему меняется цвет зубов?</h2>
<table>
<thead><tr><th>Тип окрашивания</th><th>Основные причины</th><th>Реакция на отбеливание</th></tr></thead>
<tbody>
<tr><td>Внешнее</td><td>Чай, кофе, красное вино, табачные изделия, некоторые ополаскиватели, поверхностные отложения</td><td>Обычно отвечает заметнее; чаще всего рассматривается вместе с чисткой и полировкой</td></tr>
<tr><td>Внутреннее</td><td>Возрастные изменения дентина, изменение цвета после травмы, нарушения развития, приём некоторых препаратов в анамнезе</td><td>Реакция более изменчива; в ряде случаев одного отбеливания может быть недостаточно</td></tr>
<tr><td>Смешанное</td><td>Сочетание перечисленного выше</td><td>Порядок и метод определяются по данным осмотра</td></tr>
</tbody>
</table>
<h2>Что отбеливание меняет, а что нет?</h2>
<p>Отбеливание действует только на собственные ткани зуба. <strong>Цвет имеющихся во рту пломб, коронок, мостов, виниров и протезов на имплантах не меняется.</strong> Это важно для людей с видимыми реставрациями во фронтальном отделе: когда собственные зубы светлеют, имеющиеся реставрации могут остаться более тёмными, и появится несовпадение по цвету.</p>
<p>Если такая вероятность есть, это обсуждается на осмотре заранее. У части людей после того, как цвет установится, может встать вопрос о замене видимых реставраций; это отдельная тема планирования, которая рассматривается на страницах <a href="/ru/zirkonyum-dis-kaplama/">Циркониевые коронки</a> и <a href="/ru/gulus-tasarimi/">Индивидуальный дизайн улыбки</a>.</p>
<h2>Что оценивается на осмотре?</h2>
<ul>
<li>Наличие кариеса, трещин, стираемости и негерметичных реставраций</li>
<li>Здоровье дёсен, глубина карманов и наличие рецессии</li>
<li>Обнажённая поверхность корня и имеющаяся чувствительность</li>
<li>Состояние пульпы и травма в анамнезе</li>
<li>Тип и распространённость окрашивания</li>
<li>Расположение имеющихся пломб, коронок и виниров</li>
<li>Характер смыкания, привычка сжимать зубы и скрежетать ими</li>
<li>Беременность и грудное вскармливание, а также общая история здоровья</li>
</ul>
<p>О том, что оценивается при первом осмотре в целом, вы можете прочитать на странице <a href="/ru/ilk-dis-muayenesi-tedavi-planlamasi/">Первый осмотр и планирование лечения</a>.</p>
<h2>В каких случаях процедуру откладывают?</h2>
<p>При нелеченом кариесе, негерметичной пломбе, активном воспалении дёсен или выраженной чувствительности отбеливание откладывают до устранения этих проявлений. В период беременности и грудного вскармливания отбеливание с эстетической целью обычно переносят. При выраженных внутренних окрашиваниях, нарушениях развития эмали или при большом числе видимых реставраций ожидаемый результат может быть ограниченным; в таком случае варианты и различия между ними обсуждаются вместе на осмотре.</p>
<h2>Какие есть методы?</h2>
<table>
<thead><tr><th>Метод</th><th>Как выполняется</th><th>Отличительная черта</th></tr></thead>
<tbody>
<tr><td>Клинический</td><td>Отбеливающий состав наносится под наблюдением врача и под контролем, с защитой дёсен и мягких тканей</td><td>Процедура проводится в клинике; доза и время под контролем врача</td></tr>
<tr><td>Домашний под наблюдением врача</td><td>По слепку изготавливается индивидуальная каппа; количество геля, ежедневное время ношения и общая длительность определяются врачом</td><td>Идёт более постепенно; зависит от дисциплины применения</td></tr>
<tr><td>Комбинированный</td><td>В подходящих случаях клиническая процедура планомерно сочетается с домашним применением</td><td>Порядок и длительность определяются индивидуально</td></tr>
<tr><td>Отбеливание одного зуба</td><td>Протокол, применяемый изнутри зуба при потемневшем зубе после лечения корневых каналов</td><td>Только в подходящих случаях; состояние зуба оценивается отдельно</td></tr>
</tbody>
</table>
<p>Выбор метода зависит от типа окрашивания, наличия чувствительности, имеющихся во рту реставраций и повседневного распорядка человека. Ни один метод не превосходит остальные для всех.</p>
<h2>Как проходит процесс?</h2>
<ol>
<li><strong>Осмотр и фиксация цвета.</strong> Проводится клиническая оценка, при необходимости назначается визуализация и фиксируется исходный оттенок.</li>
<li><strong>Подготовка.</strong> Устраняются кариес, негерметичные реставрации и проблемы дёсен; выполняются чистка и полировка.</li>
<li><strong>Информирование и согласие.</strong> Разъясняются ожидаемый диапазон изменения, возможная чувствительность, то, что цвет реставраций не изменится, и вероятность последующей коррекции.</li>
<li><strong>Выполнение.</strong> В зависимости от выбранного протокола проводится в клинике, дома или обоими способами.</li>
<li><strong>Контроль.</strong> После того как цвет установится, результат оценивается; необходимость коррекции определяется на этом приёме.</li>
</ol>
<h2>Чувствительность и возможные эффекты</h2>
<p>Наиболее частый эффект — временная чувствительность к горячему и холодному. Возможно и временное раздражение десны. Эти явления обычно проходят вскоре после завершения процедуры. У людей с чувствительностью в анамнезе доза, время применения и интервал между сеансами планируются соответствующим образом; при необходимости добавляются вспомогательные средства.</p>
<p>Если чувствительность длится дольше ожидаемого, нарастает или на десне появляется незаживающий участок, вам следует позвонить в клинику. Продлевать применение по собственному решению или увеличивать количество геля — значит усилить чувствительность.</p>
<h2>Насколько стойким будет результат?</h2>
<p>Стойкость индивидуальна. На срок напрямую влияют красящие напитки, употребление табака, привычки гигиены полости рта и строение поверхности зуба. В первые дни после процедуры рекомендуется ограничить тёмные напитки и продукты. С течением времени частичный возврат оттенка является обычным; необходимость коррекции определяется на контрольном осмотре.</p>
<h2>Отбеливающие средства из магазина</h2>
<p>Продающиеся без рецепта отбеливающие полоски, карандаши и гели, применённые без оценки состояния полости рта, могут не дать ожидаемого результата. Главная проблема при этом может остаться незамеченной: если причиной потемнения являются кариес, негерметичная пломба или изменение пульпы после травмы, нанесённое на поверхность средство этого не исправит и отсрочит постановку диагноза.</p>
<p>Отбеливающие пасты с абразивными компонентами и домашние способы вроде соды со временем могут стирать поверхность эмали; обнажившийся дентин выглядит более жёлтым, а чувствительность может усилиться. Если вы рассматриваете какое-либо средство, безопаснее спросить о нём на осмотре.</p>
<h2>Часто задаваемые вопросы</h2>
<p><strong>Вредит ли отбеливание эмали?</strong><br>При наличии показаний, под наблюдением врача и в рекомендованной дозе и длительности отбеливание является устоявшейся процедурой. Риск в большей степени связан с бесконтрольным применением, превышением дозы и продлением процедуры по собственному решению.</p>
<p><strong>На сколько тонов осветлятся зубы?</strong><br>Число заранее назвать нельзя. Результат определяют исходный цвет, тип окрашивания, строение зуба и личная реакция. На осмотре обсуждается ожидаемый диапазон изменения.</p>
<p><strong>Отбелятся ли мои коронки?</strong><br>Нет. Цвет пломб, коронок, мостов и виниров не меняется. Когда собственные зубы светлеют, эти реставрации могут остаться более тёмными; если такая вероятность есть, это обсуждается заранее.</p>
<p><strong>У меня чувствительные зубы — можно ли всё-таки отбеливать?</strong><br>В большинстве случаев это можно рассмотреть. Сначала выясняется причина чувствительности; при обнажённой поверхности корня, трещинах или кариесе они устраняются. Протокол адаптируется с учётом чувствительности.</p>
<p><strong>Заменяет ли отбеливание удаление зубных отложений?</strong><br>Нет. Это разные процедуры. Чистка удаляет отложения с поверхности зуба; отбеливание направлено на изменение оттенка собственных тканей зуба.</p>
<p><strong>У меня потемнел один зуб — что можно сделать?</strong><br>Потемнение одного зуба чаще всего связано с травмой или лечением корневых каналов в анамнезе. После оценки витальности зуба и состояния тканей у верхушки корня обсуждаются внутреннее отбеливание или реставрационные варианты. В этом вопросе может помочь и страница <a href="/ru/kanal-tedavisi/">Лечение корневых каналов</a>.</p>
<p><strong>Как часто можно повторять процедуру?</strong><br>Интервал повторения определяется индивидуально. Поскольку частое повторение может усиливать чувствительность, решение принимается по данным контрольного осмотра.</p>
<h2>Оценка на месте</h2>
<p>В нашей клинике на стыке районов Бейликдюзю и Эсенюрт отбеливание зубов планируется после совместной оценки типа окрашивания, здоровья дёсен, имеющихся реставраций и наличия чувствительности. Ожидаемое изменение и необходимый уход разъясняются до процедуры.</p>
<p><a href="/ru/estetik/">Эстетическая стоматология</a> &middot; <a href="/ru/gulus-tasarimi/">Индивидуальный дизайн улыбки</a> &middot; <a href="/ru/zirkonyum-dis-kaplama/">Циркониевые коронки</a> &middot; <a href="/ru/tedavi-plani-ve-surec/">План лечения и его ход</a> &middot; <a href="/ru/iletisim">Запись и контакты</a></p>',
'Клиническое, домашнее и комбинированное отбеливание зубов: кому оно подходит, почему возникает чувствительность, насколько стойким будет результат?',
'Отбеливание зубов: методы, показания и чувствительность | MSc. Dt. Mehmet Taş',
'RU' FROM treatments WHERE link = 'dis-beyazlatma';

